import React, { ReactNode } from 'react';
import { isElement } from 'react-is';

import { TooltipSubheader } from '../section-components/TooltipSubheader.js';

export const iterateHeaderSlots = (children: React.ReactNode) => {
  const headerSlots: {
    header: ReactNode[];
    subHeader: ReactNode[];
  } = { header: [], subHeader: [] };

  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      switch (child.type) {
        case TooltipSubheader: {
          headerSlots.subHeader.push(child.props.children);
          break;
        }
        default: {
          headerSlots.header.push(child);
        }
      }
    }
  });

  return headerSlots;
};
